raw = io.open(P, "rb").read()
text = raw.decode("utf-8")
assert '"tick": 2499,' in text
text = text.replace('"tick": 2499,', '"tick": 2500,', 1)
tail = '\r\n  ]\r\n}\r\n'
assert text.endswith(tail), repr(text[-40:])
